unsigned checks=0;
void check(bool value,const char* expr,int line){++checks;if(!value)throw std::runtime_error(std::string("line ")+std::to_string(line)+": "+expr+" Win32="+std::to_string(GetLastError()));}
#define CHECK(x) check(bool(x),#x,__LINE__)
template<class T>T take(Observation<T> value){if(!value.value()){const auto& e=*value.unavailable_detail();std::fprintf(stderr,"UNAVAILABLE state=%d domain=%d code=%lld operation=%s\n",int(e.state),int(e.error.domain),static_cast<long long>(e.error.code),e.error.operation.c_str());throw std::runtime_error("required native observation unavailable");}return std::move(value).take_value();}
struct Handle {HANDLE h=INVALID_HANDLE_VALUE;explicit Handle(HANDLE value):h(value){CHECK(h&&h!=INVALID_HANDLE_VALUE);}~Handle(){if(h&&h!=INVALID_HANDLE_VALUE)CloseHandle(h);}void close(){const HANDLE old=h;h=INVALID_HANDLE_VALUE;CHECK(CloseHandle(old));}Handle(const Handle&)=delete;Handle& operator=(const Handle&)=delete;};
std::wstring extended(std::wstring p){if(p.starts_with(L"\\\\?\\"))return p;if(p.starts_with(L"\\\\"))return L"\\\\?\\UNC\\"+p.substr(2);CHECK(p.size()>3&&p[1]==L':'&&p[2]==L'\\');return L"\\\\?\\"+p;}
std::u16string units(const std::wstring& p){std::u16string s;s.reserve(p.size());for(const auto c:p)s.push_back(static_cast<char16_t>(c));return s;}
std::wstring wide(const std::u16string& p){std::wstring s;s.reserve(p.size());for(const auto c:p)s.push_back(static_cast<wchar_t>(c));return s;}
NativeName name(std::u16string p){auto n=NativeName::from_windows(p);CHECK(n.has_value());return std::move(*n);}
NativeName name(const char16_t* p){return name(std::u16string(p));}
NativeAbsolutePath address(const std::wstring& p){return take(NativeAbsolutePath::from_windows(units(p)));}
void mkdir_new(const std::wstring& p){CHECK(CreateDirectoryW(extended(p).c_str(),nullptr));}
bool exists(const std::wstring& p){const DWORD a=GetFileAttributesW(extended(p).c_str());if(a!=INVALID_FILE_ATTRIBUTES)return true;const DWORD e=GetLastError();CHECK(e==ERROR_FILE_NOT_FOUND||e==ERROR_PATH_NOT_FOUND);return false;}
struct Id {ULONGLONG volume=0;std::array<unsigned char,16> file{};friend bool operator==(const Id&,const Id&)=default;};
Id id(HANDLE h){FILE_ID_INFO native{};CHECK(GetFileInformationByHandleEx(h,FileIdInfo,&native,sizeof(native)));Id result;result.volume=native.VolumeSerialNumber;std::copy(std::begin(native.FileId.Identifier),std::end(native.FileId.Identifier),result.file.begin());return result;}
Id id(const std::wstring& path){Handle h(CreateFileW(extended(path).c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr));auto result=id(h.h);h.close();return result;}
std::vector<std::byte> read_file(const std::wstring& p){Handle h(CreateFileW(extended(p).c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr));FILE_ATTRIBUTE_TAG_INFO tag{};CHECK(GetFileInformationByHandleEx(h.h,FileAttributeTagInfo,&tag,sizeof(tag)));CHECK(!(tag.FileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT)));FILE_STANDARD_INFO s{};CHECK(GetFileInformationByHandleEx(h.h,FileStandardInfo,&s,sizeof(s)));CHECK(s.EndOfFile.QuadPart>=0&&s.EndOfFile.QuadPart<=16*1024*1024);const auto before=id(h.h);std::vector<std::byte> bytes(static_cast<std::size_t>(s.EndOfFile.QuadPart));std::size_t offset=0;while(offset<bytes.size()){DWORD n=0;const auto wanted=static_cast<DWORD>(std::min<std::size_t>(65536,bytes.size()-offset));CHECK(ReadFile(h.h,bytes.data()+offset,wanted,&n,nullptr)&&n&&n<=wanted);offset+=n;}std::byte tail{};DWORD n=99;CHECK(ReadFile(h.h,&tail,1,&n,nullptr)&&n==0);CHECK(id(h.h)==before);h.close();return bytes;}
void write_new(const std::wstring& p,const std::vector<std::byte>& bytes){Handle h(CreateFileW(extended(p).c_str(),GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_NEW,FILE_FLAG_OPEN_REPARSE_POINT,nullptr));CHECK(bytes.size()<=MAXDWORD);DWORD n=0;CHECK(WriteFile(h.h,bytes.data(),static_cast<DWORD>(bytes.size()),&n,nullptr)&&n==bytes.size());CHECK(FlushFileBuffers(h.h));h.close();}
std::vector<std::byte> text(const char* p){const auto* b=reinterpret_cast<const std::byte*>(p);return {b,b+std::strlen(p)};}
struct Node {Id identity;LONGLONG size,modified,changed;DWORD attributes;std::vector<std::byte> bytes;friend bool operator==(const Node&,const Node&)=default;};
using Snapshot=std::map<std::wstring,Node>;
void snapshot_at(const std::wstring& path,const std::wstring& relative,Snapshot& out){Handle h(CreateFileW(extended(path).c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr));FILE_BASIC_INFO b{};FILE_STANDARD_INFO s{};CHECK(GetFileInformationByHandleEx(h.h,FileBasicInfo,&b,sizeof(b)));CHECK(GetFileInformationByHandleEx(h.h,FileStandardInfo,&s,sizeof(s)));CHECK(!(b.FileAttributes&FILE_ATTRIBUTE_REPARSE_POINT));Node n{id(h.h),s.EndOfFile.QuadPart,b.LastWriteTime.QuadPart,b.ChangeTime.QuadPart,b.FileAttributes,{}};h.close();if(!s.Directory)n.bytes=read_file(path);out.emplace(relative,std::move(n));if(!s.Directory)return;WIN32_FIND_DATAW data{};const HANDLE scan=FindFirstFileExW((extended(path)+L"\\*").c_str(),FindExInfoBasic,&data,FindExSearchNameMatch,nullptr,0);if(scan==INVALID_HANDLE_VALUE){CHECK(GetLastError()==ERROR_FILE_NOT_FOUND);return;}for(;;){const std::wstring child=data.cFileName;if(child!=L"."&&child!=L"..")snapshot_at(path+L"\\"+child,relative+L"\\"+child,out);if(!FindNextFileW(scan,&data)){const DWORD e=GetLastError();CHECK(FindClose(scan));CHECK(e==ERROR_NO_MORE_FILES);break;}}}
Snapshot snapshot(const std::wstring& path){Snapshot s;snapshot_at(path,L".",s);return s;}
// Fixture-owned cleanup only, after all product owners have drained. Exact
// native names and handle-based dispositions; never follows a reparse point.
void remove_owned(const std::wstring& path){const DWORD attrs=GetFileAttributesW(extended(path).c_str());CHECK(attrs!=INVALID_FILE_ATTRIBUTES&&!(attrs&FILE_ATTRIBUTE_REPARSE_POINT));if(attrs&FILE_ATTRIBUTE_DIRECTORY){WIN32_FIND_DATAW data{};const HANDLE scan=FindFirstFileExW((extended(path)+L"\\*").c_str(),FindExInfoBasic,&data,FindExSearchNameMatch,nullptr,0);if(scan!=INVALID_HANDLE_VALUE){for(;;){const std::wstring child=data.cFileName;if(child!=L"."&&child!=L"..")remove_owned(path+L"\\"+child);if(!FindNextFileW(scan,&data)){const DWORD e=GetLastError();CHECK(FindClose(scan));CHECK(e==ERROR_NO_MORE_FILES);break;}}}else CHECK(GetLastError()==ERROR_FILE_NOT_FOUND);}Handle h(CreateFileW(extended(path).c_str(),DELETE|FILE_READ_ATTRIBUTES|SYNCHRONIZE,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr));FILE_ATTRIBUTE_TAG_INFO tag{};CHECK(GetFileInformationByHandleEx(h.h,FileAttributeTagInfo,&tag,sizeof(tag)));CHECK(!(tag.FileAttributes&FILE_ATTRIBUTE_REPARSE_POINT));FILE_DISPOSITION_INFO disposition{TRUE};CHECK(SetFileInformationByHandle(h.h,FileDispositionInfo,&disposition,sizeof(disposition)));h.close();}
void sharing_guard(const std::wstring& stage){for(const DWORD access:{DWORD(GENERIC_WRITE),DWORD(DELETE)}){const HANDLE bad=CreateFileW(extended(stage).c_str(),access,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr);const DWORD e=GetLastError();if(bad!=INVALID_HANDLE_VALUE)CloseHandle(bad);CHECK(bad==INVALID_HANDLE_VALUE&&e==ERROR_SHARING_VIOLATION);}CHECK(!MoveFileExW(extended(stage).c_str(),extended(stage+L"-redirect").c_str(),0));CHECK(GetLastError()==ERROR_SHARING_VIOLATION);CHECK(!exists(stage+L"-redirect"));}
std::vector<std::byte> image(std::uint64_t size,const std::vector<NativeArchiveExtent>& extents){std::vector<std::byte> result(static_cast<std::size_t>(size));for(const auto& e:extents)std::copy(e.bytes.begin(),e.bytes.end(),result.begin()+static_cast<std::ptrdiff_t>(e.offset));return result;}
void verify_native(const std::wstring& path,const std::vector<std::byte>& expected,const NativeArchiveProgress& p,const Id& stage_id,bool sparse){CHECK(id(path)==stage_id);CHECK(read_file(path)==expected);Sha256 hash;hash.update(expected);CHECK(hash.digest()==p.digest);Handle h(CreateFileW(extended(path).c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr));FILE_STANDARD_INFO standard{};CHECK(GetFileInformationByHandleEx(h.h,FileStandardInfo,&standard,sizeof(standard)));CHECK(!standard.Directory&&!standard.DeletePending&&standard.NumberOfLinks==1&&static_cast<std::uint64_t>(standard.EndOfFile.QuadPart)==expected.size());if(sparse){FILE_ATTRIBUTE_TAG_INFO tag{};CHECK(GetFileInformationByHandleEx(h.h,FileAttributeTagInfo,&tag,sizeof(tag)));CHECK(tag.FileAttributes&FILE_ATTRIBUTE_SPARSE_FILE);FILE_ALLOCATED_RANGE_BUFFER query{};query.Length.QuadPart=static_cast<LONGLONG>(expected.size());std::array<FILE_ALLOCATED_RANGE_BUFFER,16> ranges{};DWORD bytes=0;CHECK(DeviceIoControl(h.h,FSCTL_QUERY_ALLOCATED_RANGES,&query,sizeof(query),ranges.data(),static_cast<DWORD>(sizeof(ranges)),&bytes,nullptr));CHECK(bytes%sizeof(ranges[0])==0&&bytes<=sizeof(ranges));std::uint64_t allocated=0,end=0;for(std::size_t i=0;i<bytes/sizeof(ranges[0]);++i){CHECK(ranges[i].FileOffset.QuadPart>=0&&ranges[i].Length.QuadPart>0);const auto lo=static_cast<std::uint64_t>(ranges[i].FileOffset.QuadPart);const auto length=static_cast<std::uint64_t>(ranges[i].Length.QuadPart);CHECK(lo>=end&&lo<=expected.size());const auto hi=lo+std::min<std::uint64_t>(length,expected.size()-lo);allocated+=hi-lo;end=hi;}CHECK(allocated<=expected.size());CHECK(expected.size()-allocated==p.unallocated_bytes);}h.close();}
bool terminal(NativeArchivePhase p){return p==NativeArchivePhase::Complete||p==NativeArchivePhase::Cancelled||p==NativeArchivePhase::NeedsReconciliation;}
