void unc_refusal(const std::wstring& base){
 Handle reachable(CreateFileW(extended(base).c_str(),FILE_READ_ATTRIBUTES|SYNCHRONIZE,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr));reachable.close();
 const auto before=snapshot(base);NativeFileSystem fs;auto opened=fs.open_native_directory(address(base));CHECK(opened.value());
 auto parent=std::shared_ptr<const DirectoryCursor>(std::move(opened).take_value());PreparedJournalRootRequest request{parent,name(u"unc-private"),JournalRootDisposition::ProvisionChild};JournalRootPreparationProgress progress;
 auto refused=prepare_native_journal_root(std::move(request),progress);CHECK(!refused.value()&&refused.state()==ObservationState::Unsupported);const auto& error=refused.unavailable_detail()->error;
 CHECK(error.domain==ErrorDomain::Adapter&&error.code==static_cast<std::int64_t>(AdapterError::PlanTopologyUnsafe)&&error.operation=="journal_scope.windows_driver_unqualified");CHECK(progress.directory_creates==0);CHECK(snapshot(base)==before);parent.reset();CHECK(snapshot(base)==before);
 std::printf("UNC reachable native PreparedRoot prerequisite REFUSED state=%d domain=%d code=%lld operation=%s creates=0 no ArchiveJob authority or data effects checks=%u\n",int(refused.state()),int(error.domain),static_cast<long long>(error.code),error.operation.c_str(),checks);
}
